/*
 * Walking rules for the guild hall. Furniture has a footprint (the part that touches the floor); fighters
 * may not step inside it, so they walk around beds, tables and shelves instead of through them.
 * Everything is in hall tiles. The hall is turned into a coarse grid, paths are found with A*, then
 * straightened so a fighter walks in clean lines rather than along grid cells.
 */

export interface NavLayout {
  cols: number;
  rows: number;
  floor: { x0: number; x1: number; y0: number; y1: number };
  props: { foot: number[] | null }[];
  /** Optional: one byte per tile, 1 where the ground can't be walked on (walls, dense woods). */
  solid?: Uint8Array;
}

export type Pt = [number, number];

export interface Nav {
  floor: NavLayout["floor"];
  solid?: Uint8Array;
  cols: number;
  feet: number[][]; // footprints, already grown by the fighter's body
  res: number; // grid cells per tile
  w: number;
  h: number;
  blocked: Uint8Array;
  /** 1 for cells in the main open area; closed-off nooks between furniture are left out so nobody gets sent there. */
  main: Uint8Array;
  /** 1 for cells in the main area that also have breathing room on every side: wide enough that a party can really walk up to them. Mobs only live and wander here. */
  roomy: Uint8Array;
}

/** How far a fighter's body reaches around its feet (tiles). Keeps shoulders from clipping into furniture. */
const BODY = 0.4;

export function buildNav(layout: NavLayout, res = 2): Nav {
  const feet = layout.props.flatMap((p) => (p.foot ? [[p.foot[0] - BODY, p.foot[1] - BODY, p.foot[2] + BODY, p.foot[3] + BODY]] : []));
  const w = layout.cols * res;
  const h = layout.rows * res;
  const nav: Nav = { floor: layout.floor, solid: layout.solid, cols: layout.cols, feet, res, w, h, blocked: new Uint8Array(w * h), main: new Uint8Array(w * h), roomy: new Uint8Array(w * h) };
  for (let j = 0; j < h; j++) {
    for (let i = 0; i < w; i++) nav.blocked[j * w + i] = walkable(nav, (i + 0.5) / res, (j + 0.5) / res) ? 0 : 1;
  }
  markMainArea(nav);
  // Cells with a free cell on all four sides, joined to the biggest such area: pockets and one-cell gaps between trees drop out.
  const eroded = new Uint8Array(w * h);
  for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) {
    const k = j * w + i;
    eroded[k] = nav.blocked[k] || i === 0 || j === 0 || i === w - 1 || j === h - 1 || nav.blocked[k - 1] || nav.blocked[k + 1] || nav.blocked[k - w] || nav.blocked[k + w] ? 1 : 0;
  }
  const core = largestOpen(w, h, eroded);
  let any = false;
  for (let k = 0; k < core.length; k++) { nav.roomy[k] = core[k] && nav.main[k] ? 1 : 0; if (nav.roomy[k]) any = true; }
  if (!any) nav.roomy.set(nav.main);
  return nav;
}

/** Flood-fills the free cells and keeps the biggest connected area. */
function markMainArea(nav: Nav) {
  nav.main = largestOpen(nav.w, nav.h, nav.blocked);
}

function largestOpen(w: number, h: number, blocked: Uint8Array): Uint8Array {
  const seen = new Int32Array(w * h).fill(-1);
  const sizes: number[] = [];
  for (let start = 0; start < seen.length; start++) {
    if (blocked[start] || seen[start] !== -1) continue;
    const id = sizes.length;
    let size = 0;
    const stack = [start];
    seen[start] = id;
    while (stack.length) {
      const k = stack.pop()!;
      size++;
      const i = k % w, j = (k - i) / w;
      for (const [di, dj] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const ni = i + di, nj = j + dj;
        if (ni < 0 || nj < 0 || ni >= w || nj >= h) continue;
        const nk = nj * w + ni;
        if (!blocked[nk] && seen[nk] === -1) { seen[nk] = id; stack.push(nk); }
      }
    }
    sizes.push(size);
  }
  const out = new Uint8Array(w * h);
  if (!sizes.length) return out;
  const best = sizes.indexOf(Math.max(...sizes));
  for (let k = 0; k < seen.length; k++) out[k] = seen[k] === best ? 1 : 0;
  return out;
}

/** Can a fighter stand here? */
export function walkable(nav: Nav, x: number, y: number): boolean {
  const f = nav.floor;
  if (x < f.x0 || x > f.x1 || y < f.y0 || y > f.y1) return false;
  if (nav.solid && nav.solid[Math.floor(y) * nav.cols + Math.floor(x)]) return false;
  for (const r of nav.feet) if (x > r[0] && x < r[2] && y > r[1] && y < r[3]) return false;
  return true;
}

const cellOf = (nav: Nav, v: number) => Math.floor(v * nav.res);
const free = (nav: Nav, i: number, j: number) => i >= 0 && j >= 0 && i < nav.w && j < nav.h && nav.blocked[j * nav.w + i] === 0;

/** Free floor that is also connected to the rest of the hall. */
export function standable(nav: Nav, x: number, y: number): boolean {
  if (!walkable(nav, x, y)) return false;
  const i = cellOf(nav, x), j = cellOf(nav, y);
  return i >= 0 && j >= 0 && i < nav.w && j < nav.h && nav.main[j * nav.w + i] === 1;
}

/** Open ground a party can properly reach: where mobs may stand and wander. */
export function roomy(nav: Nav, x: number, y: number): boolean {
  if (!walkable(nav, x, y)) return false;
  const i = cellOf(nav, x), j = cellOf(nav, y);
  return i >= 0 && j >= 0 && i < nav.w && j < nav.h && nav.roomy[j * nav.w + i] === 1;
}

/** The closest roomy spot to a point (the point itself if it already is). */
export function nearestRoomy(nav: Nav, x: number, y: number): Pt {
  if (roomy(nav, x, y)) return [x, y];
  let best: Pt | null = null, bestD = Infinity;
  for (let j = 0; j < nav.h; j++) for (let i = 0; i < nav.w; i++) {
    if (!nav.roomy[j * nav.w + i]) continue;
    const cx = (i + 0.5) / nav.res, cy = (j + 0.5) / nav.res;
    const d = (cx - x) ** 2 + (cy - y) ** 2;
    if (d < bestD) { bestD = d; best = [cx, cy]; }
  }
  return best ?? nearestWalkable(nav, x, y);
}

/** The closest standable spot to a tapped point (the point itself if it is already free). */
export function nearestWalkable(nav: Nav, x: number, y: number): Pt {
  if (standable(nav, x, y)) return [x, y];
  let best: Pt | null = null;
  let bestD = Infinity;
  for (let j = 0; j < nav.h; j++) {
    for (let i = 0; i < nav.w; i++) {
      if (!nav.main[j * nav.w + i]) continue;
      const cx = (i + 0.5) / nav.res;
      const cy = (j + 0.5) / nav.res;
      const d = (cx - x) ** 2 + (cy - y) ** 2;
      if (d < bestD) { bestD = d; best = [cx, cy]; }
    }
  }
  return best ?? [x, y];
}

/** A random standable spot, optionally close to a point. */
export function randomWalkable(nav: Nav, rand: () => number, near?: Pt, radius = 7): Pt {
  for (let n = 0; n < 40; n++) {
    const x = near ? near[0] + (rand() * 2 - 1) * radius : nav.floor.x0 + rand() * (nav.floor.x1 - nav.floor.x0);
    const y = near ? near[1] + (rand() * 2 - 1) * radius * 0.6 : nav.floor.y0 + rand() * (nav.floor.y1 - nav.floor.y0);
    if (standable(nav, x, y)) return [x, y];
  }
  return nearestWalkable(nav, (nav.floor.x0 + nav.floor.x1) / 2, (nav.floor.y0 + nav.floor.y1) / 2);
}

/** Is the straight line between two points clear of furniture? */
export function clearLine(nav: Nav, a: Pt, b: Pt): boolean {
  const dist = Math.hypot(b[0] - a[0], b[1] - a[1]);
  const steps = Math.max(1, Math.ceil(dist / 0.15));
  for (let s = 1; s <= steps; s++) {
    const t = s / steps;
    if (!walkable(nav, a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t)) return false;
  }
  return true;
}

/** A walkable route from `from` to `to` (both snapped onto the floor first). Empty if there is none. */
export function findPath(nav: Nav, from: Pt, to: Pt): Pt[] {
  const start = nearestWalkable(nav, from[0], from[1]);
  const goal = nearestWalkable(nav, to[0], to[1]);
  if (clearLine(nav, start, goal)) return [goal];

  const si = cellOf(nav, start[0]), sj = cellOf(nav, start[1]);
  const gi = cellOf(nav, goal[0]), gj = cellOf(nav, goal[1]);
  const key = (i: number, j: number) => j * nav.w + i;
  const g = new Float32Array(nav.w * nav.h).fill(Infinity);
  const from_ = new Int32Array(nav.w * nav.h).fill(-1);
  const closed = new Uint8Array(nav.w * nav.h);
  const open: { k: number; f: number }[] = [];
  const octile = (i: number, j: number) => {
    const dx = Math.abs(i - gi), dy = Math.abs(j - gj);
    return dx + dy + (Math.SQRT2 - 2) * Math.min(dx, dy);
  };
  // The start cell can itself be blocked when the fighter stands on the edge of a footprint: allow leaving it.
  g[key(si, sj)] = 0;
  open.push({ k: key(si, sj), f: octile(si, sj) });

  let found = false;
  while (open.length) {
    let bi = 0;
    for (let n = 1; n < open.length; n++) if (open[n].f < open[bi].f) bi = n;
    const cur = open.splice(bi, 1)[0];
    if (closed[cur.k]) continue;
    closed[cur.k] = 1;
    const ci = cur.k % nav.w, cj = (cur.k - ci) / nav.w;
    if (ci === gi && cj === gj) { found = true; break; }
    for (let dj = -1; dj <= 1; dj++) {
      for (let di = -1; di <= 1; di++) {
        if (!di && !dj) continue;
        const ni = ci + di, nj = cj + dj;
        if (!free(nav, ni, nj) || closed[key(ni, nj)]) continue;
        if (di && dj && (!free(nav, ci + di, cj) || !free(nav, ci, cj + dj))) continue; // no cutting corners
        const cost = g[cur.k] + (di && dj ? Math.SQRT2 : 1);
        if (cost < g[key(ni, nj)]) {
          g[key(ni, nj)] = cost;
          from_[key(ni, nj)] = cur.k;
          open.push({ k: key(ni, nj), f: cost + octile(ni, nj) });
        }
      }
    }
  }
  if (!found) return [];

  const cells: Pt[] = [];
  for (let k = key(gi, gj); k !== -1; k = from_[k]) {
    const i = k % nav.w;
    cells.push([(i + 0.5) / nav.res, ((k - i) / nav.w + 0.5) / nav.res]);
  }
  cells.reverse();
  cells[0] = start;
  cells[cells.length - 1] = goal;

  // Straighten: from each anchor, jump to the furthest point still in clear sight.
  const path: Pt[] = [];
  let anchor = 0;
  while (anchor < cells.length - 1) {
    let far = anchor + 1;
    for (let n = cells.length - 1; n > anchor + 1; n--) {
      if (clearLine(nav, cells[anchor], cells[n])) { far = n; break; }
    }
    path.push(cells[far]);
    anchor = far;
  }
  return path;
}
